    if (root == NULL) return 0;

    std::queue<Node*> q;
    q.push(root);
    int currentLevel = 0;
    int keyCount = 0;

    while (!q.empty()) {
        int sz = q.size();

        if (currentLevel == level) {
            for (int i = 0; i < sz; i++) {
                Node* u = q.front();
                q.pop();
                keyCount += u->keys.size();
            }
            return keyCount;
