        for (int i = 0; i < sz; i++) {
            Node* u = q.front();
            q.pop();

            if (u->isLeaf != true) {
                for (Node* v : u->ptr2TreeOrData.ptr2Tree) {
                    q.push(v);
                }
            }
        }
        currentLevel++;
    }

    return 0;
}

